import{_ as a,o,c as i,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"14.1 实操考核概述与评分标准","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md"};function e(n,t,s,h,d,u){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_14-1-实操考核概述与评分标准" tabindex="-1">14.1 实操考核概述与评分标准 <a class="header-anchor" href="#_14-1-实操考核概述与评分标准" aria-label="Permalink to &quot;14.1 实操考核概述与评分标准&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>低压电工考证分<strong>理论</strong>和<strong>实操</strong>两部分。这一节总览实操考什么、怎么评分,帮你在动手之前先明白&quot;考官看重什么&quot;。</p><h2 id="一、实操考核考什么" tabindex="-1">一、实操考核考什么 <a class="header-anchor" href="#一、实操考核考什么" aria-label="Permalink to &quot;一、实操考核考什么&quot;">​</a></h2><p>低压电工实操考核一般围绕&quot;安全第一&quot;展开,常见考核项目:</p><table tabindex="0"><thead><tr><th>考核项目</th><th>内容举例</th></tr></thead><tbody><tr><td><strong>安全操作</strong></td><td>安全用具使用、验电、断电操作、安全距离</td></tr><tr><td><strong>仪表使用</strong></td><td>万用表、钳形表、兆欧表的使用</td></tr><tr><td><strong>线路接线</strong></td><td>照明电路接线、电动机控制线路接线、配电箱接线</td></tr><tr><td><strong>电能表接线</strong></td><td>单相/三相电能表的正确接线</td></tr><tr><td><strong>触电急救</strong></td><td>脱离电源、心肺复苏、伤口处理</td></tr></tbody></table><blockquote><p>💡 实操的核心考核理念:<strong>&quot;安全操作永远比完成接线更重要&quot;</strong>——即使线路接得快,只要有不安全行为,一样被扣分甚至判不合格。</p></blockquote><h2 id="二、评分思路-安全扣分最狠" tabindex="-1">二、评分思路(安全扣分最狠) <a class="header-anchor" href="#二、评分思路-安全扣分最狠" aria-label="Permalink to &quot;二、评分思路(安全扣分最狠)&quot;">​</a></h2><p>实操评分一般从&quot;开始答题&quot;起就有安全行为分:</p><ul><li><strong>穿戴要求</strong>:是否按规定穿工作服、绝缘鞋,戴安全帽(部分考场);</li><li><strong>工具使用</strong>:工具选择是否正确、使用是否规范;</li><li><strong>操作流程</strong>:是否先断电、后验电、再操作;</li><li><strong>接线质量</strong>:接线是否正确、牢固、美观;</li><li><strong>收尾检查</strong>:完成后是否检查、是否清理现场、是否正确送电(试车)。</li></ul><blockquote><p>⚠️ <strong>一票否决项</strong>(各考场规定不同,务必遵守):如<strong>带电作业、接线错误导致短路、不按要求穿戴绝缘防护</strong>等严重不安全行为,可能直接判不合格。</p></blockquote><h2 id="三、实操考核流程-通用模式" tabindex="-1">三、实操考核流程(通用模式) <a class="header-anchor" href="#三、实操考核流程-通用模式" aria-label="Permalink to &quot;三、实操考核流程(通用模式)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>抽题/候场 → 讲解安全要求 → 按题操作 → 考官检查评分 → 收尾</span></span></code></pre></div><ul><li>操作前认真听清题目要求;</li><li>操作中<strong>边做边口述</strong>(很多考场要求叙述步骤),条理清晰;</li><li>操作后<strong>主动检查、汇报完成</strong>。</li></ul><h2 id="四、备考建议" tabindex="-1">四、备考建议 <a class="header-anchor" href="#四、备考建议" aria-label="Permalink to &quot;四、备考建议&quot;">​</a></h2><ol><li>把安全规范练成<strong>肌肉记忆</strong>:断电、验电、绝缘防护每一步都到位;</li><li><strong>熟悉接线图</strong>:自锁、正反转、星三角要能独立完成接线;</li><li>多练仪表:万用表测电压、电阻,兆欧表测绝缘,动作要规范;</li><li>急救技能反复练:心肺复苏的位置、频率、比例要标准。</li></ol><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 实操核心:<strong>安全第一</strong>,不安全行为扣分最重。</li><li>✅ 评分看穿戴、流程、接线质量、收尾检查。</li><li>✅ 操作时边做边口述步骤。</li><li>⚠️ 易混点:实操不是&quot;接线越快越好&quot;,而是&quot;流程规范、安全到位&quot;。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>实操考:安全操作、仪表、接线、急救。</li><li>评分重点在安全行为和操作规范。</li><li>备考:练安全习惯、练接线、练仪表、练急救。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)实操考核中,安全操作行为比接线速度更重要。( )</li><li>(单选)实操考核一般不包括下列哪一项?() A. 万用表使用　B. 心肺复苏　C. 电动机控制线路接线　D. 理论计算题</li><li>(判断)实操操作过程中,边操作边口述步骤,有助于得分。( )</li><li>(判断)实操考核中出现严重不安全行为,可能被直接判不合格。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。安全第一,安全行为权重最高。</li><li><strong>D</strong>。实操考的是动手项目,不含理论计算。</li><li><strong>√</strong>。口述步骤体现条理和规范。</li><li><strong>√</strong>。严重不安全行为可一票否决。</li></ol></details>',23)])])}const p=a(r,[["render",e]]);export{c as __pageData,p as default};
